import{t as n}from"./escapeHTML.BNmQUQUh.chunk.js";var t=[{id:1,title:"Какие виды работ вы выполняете?",description:"Я оказываю полный спектр сантехнических услуг: установку и замену сантехники, ремонт труб и систем отопления, прочистку труб, монтаж водоснабжения и канализации, устранение протечек и засоров."},{id:2,title:"Можно ли заказать услугу сантехника в выходной день?",description:"Да, я работаю без выходных и могу принять ваш вызов в любое удобное время."},{id:3,title:"Как я могу узнать стоимость услуг?",description:"Стоимость зависит от типа работ и сложности задачи. Вы можете получить предварительную консультацию и ориентировочную цену по телефону или при личном осмотре объекта."},{id:4,title:"Какие способы оплаты вы принимаете?",description:"Оплату можно произвести наличными или на банковскую карту."},{id:5,title:"Какие гарантии вы предоставляете на работы?",description:"Я даю гарантию на все выполненные работы сроком от 6 месяцев до 2 лет в зависимости от вида услуги."},{id:6,title:"Могу ли я самостоятельно приобрести материал для работы?",description:"Да, вы можете предоставить свои материалы. Однако я рекомендую доверять выбор материалов специалисту для гарантии качества и совместимости."}];async function i(){const i=document.querySelector("#questions .accordion");try{const c=t;i.innerHTML="",c.forEach(t=>{const c=document.createElement("li");c.className="accordion__item",c.innerHTML=`\n            <button class="accordion__btn btn-reset">\n            <span class="accordion__text">${n(t.title)}</span>\n            <span class="accordion__icon"></span>\n            </button>\n            <div class="accordion-box">\n            <p class="accordion-box__text">${n(t.description)}</p>\n            </div>`,i.append(c)})}catch(c){i.innerHTML="<li>Не удалось загрузить услуги. Пожалуйста, попробуйте позже.</li>"}}export{i as questionsList};